use liq_ta::kernels::simd::*;
fn bits(x:f64)->u64 { if x.is_nan(){f64::NAN.to_bits()} else {x.to_bits()} }
fn main(){ for len in 0..=65 {for mode in 0..6 {let mut x:Vec<f64>=(0..len).map(|i| {let a=f64::from(u8::try_from(i%11).unwrap())/7.0; if i%2==0 {a} else {-a}}).collect(); if mode==1 && len>0 {x[len/2]=f64::NAN;} if mode==2 && len>0 {x[len/2]=f64::INFINITY;} if mode==3 {for (i,v) in x.iter_mut().enumerate(){*v=[1e16,1.0,-1e16,1.0][i%4];}} if mode==4 {for (i,v) in x.iter_mut().enumerate(){*v=if i%2==0 {0.0} else {-0.0};}} if mode==5 {for (i,v) in x.iter_mut().enumerate(){*v=if i%2==0 {f64::MIN_POSITIVE} else {-f64::MIN_POSITIVE};}} let y:Vec<f64>=x.iter().map(|v| v*0.75).collect(); let (s,c)=sum_and_count_f64(&x); let (a,b,n)=sum_and_sum_sq_and_count_f64(&x); let (m1,m2,m3,m4)=moments_f64(&x); let (m5,m6,m7,m8,k)=moments_and_count_f64(&x); let (c1,c2,c3,c4,c5)=covariance_components_f64(&x,&y); let mut output=vec![0.0;len]; lagged_sub_sanitize_f64(&x,&y,&mut output); println!("{len}:{mode} {:?} {c} {n} {k} {:?}", [sum_f64(&x),min_f64(&x),max_f64(&x),s,a,b,sum_of_squares_f64(&x),dot_product_f64(&x,&y),m1,m2,m3,m4,m5,m6,m7,m8,c1,c2,c3,c4,c5].map(bits), output.into_iter().map(bits).collect::<Vec<_>>()); }} }
